/* Original editorial lesson plans and diagram briefs. Times include practice. */
const lessonGuides = {
  body: {
    goal: 'Notice your dog’s signals and respond with the space or choice they need.',
    kit: ['A quiet place to observe', 'A notebook or phone for observations', 'A way for your dog to move away'],
    note: 'These illustrations are simplified examples, not a diagnosis. Read the whole dog and the situation, especially when signals are mixed.',
    source: 'https://www.battersea.org.uk/pet-advice/dog-advice/understanding-your-dogs-body-language',
    sourceName: 'Battersea: understanding dog body language',
    steps: [
      { title: 'Start with their comfortable baseline', art: 'look', labels: ['Soft expression', 'Loose body'], instructions: 'Watch your dog from a comfortable distance while they are relaxed at home. Notice how their ears, face, tail and body usually look. Observe without calling, touching or asking them to perform.', why: 'Knowing their normal posture makes changes easier to notice. A curled tail or naturally upright ears can mean different things on different dogs.', practice: 'Write down two things you notice when your dog is comfortable. Keep this first observation short.', fix: 'If they watch you tensely or turn away, increase your distance. You do not need to approach to learn.', alt: 'Diagram of a dog with a loose standing posture, soft eyes and a gently curved tail, with labels pointing to expression and body.' },
      { title: 'Notice tension and offer distance', art: 'space', labels: ['Pause your approach', 'Leave an exit'], instructions: 'Look for a change such as a sudden freeze, a stiff body or turning the head away as someone approaches. Pause the interaction. Step back calmly and leave a clear route for the dog to move away.', why: 'Responding to early signals can keep a dog from needing to communicate more strongly. A tail wag by itself does not tell you they want contact.', practice: 'Identify a place in your home where your dog can rest without being followed or touched.', fix: 'Do not test a dog by approaching repeatedly. If you are worried about fear or aggression, seek a qualified reward-based behaviour professional.', alt: 'Diagram showing a person stopping several steps away from a dog, with a clear open exit behind the dog.' },
      { title: 'Let contact be a choice', art: 'choice', labels: ['Invite, don’t reach', 'They can walk away'], instructions: 'Stay still and let your dog decide whether to come closer. If they enjoy gentle contact, pause after a short moment. Notice whether they move back toward you or choose to leave. Respect either response.', why: 'Giving choice helps you learn what your own dog enjoys. Staying nearby does not automatically mean a dog wants to be touched.', practice: 'During a familiar, relaxed interaction, pause once and observe what your dog chooses next.', fix: 'If your dog is resting, eating, hiding or caring for puppies, leave them undisturbed. Children need active adult supervision around dogs.', alt: 'Diagram of a seated person with hands resting on their lap while a dog has two open paths: approach or move away.' },
      { title: 'Put the signals in context', art: 'observe', labels: ['What changed?', 'Respond kindly'], instructions: 'Think about what happened just before the behaviour: a loud sound, a visitor, a new place or handling. Compare several signals with your dog’s usual baseline. Record what you changed and whether they appeared more comfortable afterward.', why: 'A single picture or gesture cannot explain the whole situation. Looking for patterns is more useful than giving every movement a fixed meaning.', practice: 'Make one short note: situation, signals seen, and the change you made to help.', fix: 'Sudden or unusual behaviour can have a health cause. Speak with your vet if the change is new, persistent or accompanied by signs of illness.', alt: 'Diagram of a simple observation notebook beside a dog, with fields for situation, body signals and the helpful response.' }
    ]
  },
  potty: {
    goal: 'Build a predictable toilet routine and reward the right place without pressure.',
    kit: ['An accessible outdoor toilet spot', 'A lead if the space is not secure', 'Small rewards', 'A pet-safe cleaner and a simple log'],
    note: 'Never limit access to drinking water to prevent accidents. If toileting changes suddenly, your dog strains, or they seem unwell, contact your vet.',
    source: sources.potty, sourceName: 'RSPCA: toilet training',
    steps: [
      { title: 'Make opportunities predictable', art: 'routine', labels: ['Wake · Eat · Play', 'Offer a toilet break'], instructions: 'Offer a toilet trip after waking, eating and playing, and before bed. Add frequent opportunities between these events according to your dog’s age and needs. Choose an easy-to-reach toilet area and use the same route at first.', why: 'A routine creates chances to succeed before the dog has to signal urgently. Puppies and newly adopted adults may need extra support.', practice: 'Write your next three likely toilet opportunities in a log. Avoid assuming every dog can wait the same amount of time.', fix: 'If accidents happen between trips, shorten the gap. A schedule is a starting point, not a test of bladder control.', alt: 'Diagram of a daily routine with waking, a meal and play linked by arrows to an outdoor toilet area.' },
      { title: 'Go with them and wait calmly', art: 'outside', labels: ['Same quiet spot', 'Stay nearby'], instructions: 'Accompany your dog to the toilet area. Keep the outing calm and allow time to sniff. If the area is not enclosed, use a lead without pulling. Watch for signs such as circling or focused sniffing.', why: 'Being nearby lets you notice success and reward at the right moment. Sending a dog out alone makes the timing harder.', practice: 'On your next planned trip, focus on observing rather than repeatedly asking the dog to toilet.', fix: 'If nothing happens, return indoors calmly, supervise closely and offer another opportunity soon. Do not force a long wait outside.', alt: 'Diagram of a handler waiting calmly near a dog sniffing a grassy toilet area on a slack lead.' },
      { title: 'Reward as soon as they finish', art: 'reward', labels: ['Finish first', 'Then reward'], instructions: 'When your dog finishes toileting in the right place, give praise and a small reward promptly. If you want a toilet cue, say it quietly while the behaviour is happening; do not repeat it continuously before they understand it.', why: 'Clear timing connects the reward with the location and behaviour you want to encourage.', practice: 'Have a reward ready before you go out, then deliver it after your dog finishes.', fix: 'Avoid interrupting the dog with an excited celebration. Keep your response friendly and calm.', alt: 'Diagram of a dog in the outdoor toilet area receiving a small treat after finishing, shown as a two-part finish-then-reward sequence.' },
      { title: 'Treat accidents as information', art: 'clean', labels: ['Clean calmly', 'Adjust the routine'], instructions: 'Clean indoor accidents with a pet-safe product and follow its instructions. Do not scold or rub a dog’s nose in a mess. Note when it happened and what came before it, then adjust supervision and toilet opportunities.', why: 'Punishment can make dogs reluctant to toilet near you. A record helps you spot a routine that needs changing.', practice: 'Log one successful trip or accident with its time and the activity before it. Look for a pattern over several days.', fix: 'A dog that was reliable and suddenly has accidents may need a veterinary check before you treat it as a training problem.', alt: 'Diagram showing a cleaner and cloth beside a simple toilet log, with a calm dog kept away from the cleaning product.' }
    ]
  },
  sit: {
    goal: 'Teach a voluntary sit using clear timing and a reward your dog enjoys.',
    kit: ['A quiet, non-slip surface', 'Small food rewards or another suitable reward', 'A short session with breaks'],
    note: 'Do not press a dog’s hips down. If sitting looks uncomfortable or difficult, stop and ask your vet about it.',
    source: sources.train, sourceName: 'RSPCA: reward-based training',
    steps: [
      { title: 'Choose an easy place and a reward', art: 'treat', labels: ['Quiet space', 'Tiny rewards'], instructions: 'Begin away from exciting distractions on a surface where your dog can stand comfortably. Prepare several small rewards and let your dog notice that you have something they enjoy. Keep your body relaxed.', why: 'An easy environment lets the dog focus on a new movement rather than on everything happening around them.', practice: 'Reward one moment of calmly looking toward you. Then give the dog a short break.', fix: 'If your dog will not eat, they may be full, worried or distracted. Change the setting or pause rather than increasing pressure.', alt: 'Diagram of a standing dog on a non-slip rug facing a handler holding a few small training treats.' },
      { title: 'Guide the nose gently upward', art: 'lure', labels: ['Close to the nose', 'Small upward arc'], instructions: 'Hold a treat close to the nose. Move it slowly upward and a little back over the head. Let the dog follow it voluntarily. Use a small movement rather than lifting the reward so high that the dog jumps.', why: 'Following the reward can encourage the dog to shift their weight and lower their bottom naturally.', practice: 'Try one slow lure. If your dog follows even part of the movement calmly, make the next attempt easier.', fix: 'If they back away or jump, lower your hand and make the movement smaller. Never push the dog into position.', alt: 'Diagram showing a hand with a treat near a dog’s nose and a short curved arrow moving upward and slightly back.' },
      { title: 'Mark the sit and deliver the reward', art: 'sit', labels: ['Bottom touches down', 'Yes → reward'], instructions: 'The moment their bottom touches the floor, say a short marker such as “yes” and give the reward. Allow them to stand again between repetitions. A few calm successes are enough for a first session.', why: 'The marker identifies the exact action that earned the reward. Rewarding promptly keeps the message clear.', practice: 'Aim for one or two comfortable sits with a break between them, not a long sequence.', fix: 'If the dog lies down instead, reset calmly. Reward the next clear sit and keep your lure close and controlled.', alt: 'Diagram of a dog sitting voluntarily while a handler offers a reward and a speech bubble marks the moment with “yes”.' },
      { title: 'Add the word, then reduce the lure', art: 'cue', labels: ['Say “sit” once', 'Keep rewarding'], instructions: 'When the movement becomes familiar, say “sit” just before you make the hand movement. Gradually use the same gesture without food visibly in your hand, then deliver a reward from your other hand or a pouch.', why: 'This transfers information from the visible food to your cue. It takes repeated easy practice, not a sudden test without help.', practice: 'Try one repetition with a smaller gesture. If it is confusing, return to the previous successful version.', fix: 'Do not repeat the word over and over. Make the situation easier and help the dog succeed before adding distractions.', alt: 'Diagram of a seated dog responding to a simple hand signal and the word “sit”, with the reward kept separately in a pouch.' }
    ]
  },
  recall: {
    goal: 'Make coming back to you a safe, rewarding choice in gradually harder situations.',
    kit: ['A secure enclosed practice space', 'High-value rewards', 'A suitable harness and long line for later practice'],
    note: 'Keep an unproven recall away from roads, livestock and other hazards. A successful indoor exercise does not make off-lead practice safe everywhere.',
    source: 'https://www.dogstrust.org.uk/dog-advice/training/basics/recall-training', sourceName: 'Dogs Trust: recall training',
    steps: [
      { title: 'Begin close by in a secure space', art: 'enclosed', labels: ['Secure boundary', 'Start nearby'], instructions: 'Choose an enclosed, quiet area. Begin only a short distance from your dog while they are likely to notice you. Prepare a reward that is worth leaving their current activity for.', why: 'Starting close and easy creates successful repetitions before you ask for distance or distractions.', practice: 'Wait for a moment when your dog is available to engage. Avoid beginning when they are deeply focused on another dog or scent.', fix: 'If you cannot safely contain the area, keep suitable management in place. Do not use an open space to test a new skill.', alt: 'Diagram of a dog and handler a short distance apart inside a clearly fenced practice area.' },
      { title: 'Invite a return with one cheerful cue', art: 'call', labels: ['One clear cue', 'Invite movement'], instructions: 'Say your dog’s name and recall cue once in a warm voice. Make yourself inviting with a relaxed posture. If appropriate, moving a little away can encourage the dog to follow toward you.', why: 'A clear invitation is easier to understand than repeated shouting. The cue should predict something good.', practice: 'Call once from a short distance and reward any willing movement toward you as you build the whole return.', fix: 'If there is no response, reduce the distance or distraction next time. Avoid repeatedly using the cue when success is unlikely.', alt: 'Diagram of a handler giving one cheerful recall cue while a curved path shows the dog moving toward them.' },
      { title: 'Reward the arrival, then release', art: 'return', labels: ['Reward near you', 'Return to safe fun'], instructions: 'Reward generously when your dog reaches you. Keep the arrival friendly. Often let them return to a safe activity afterward so that coming back does not always mean the walk or play ends.', why: 'The reward builds value in returning, and a release helps recall remain worthwhile even when the environment is interesting.', practice: 'Practise one return, reward near your body, then give a familiar release and let your dog resume safe exploration.', fix: 'Never punish a dog when they finally return, even if it took longer than you hoped. Make the next repetition easier.', alt: 'Diagram showing a dog arriving close to the handler for a reward, followed by an arrow back to a safe sniffing activity.' },
      { title: 'Change one difficulty at a time', art: 'distance', labels: ['Distance OR distraction', 'Keep a safety line'], instructions: 'Gradually practise in other safe settings. Change distance or distraction in small steps rather than both at once. Where appropriate, use a long line attached to a suitable harness, handled so it does not tangle or create a trip hazard.', why: 'A dog needs practice in different situations. Management keeps everyone safe while the response is still developing.', practice: 'Choose one slightly harder repetition. If your dog struggles, return to the easier version where they were successful.', fix: 'A long line is management, not a tool to jerk the dog back. Ask a reward-based trainer for help with safe handling if needed.', alt: 'Diagram of a dog practising at a slightly greater distance on a loose long line attached to a harness, inside a safe area.' }
    ]
  },
  task: {
    goal: 'Teach your dog to choose a mat as a useful station, with a clear release.',
    kit: ['A comfortable non-slip mat', 'Small rewards', 'A quiet room with room to leave the mat'],
    note: 'A mat station is a learned task, not a guarantee of relaxation. Keep the dog’s rest needs and freedom to take breaks in mind.',
    source: 'https://www.dogstrust.org.uk/dog-advice/training/basics/settle-training', sourceName: 'Dogs Trust: settling and calm practice',
    steps: [
      { title: 'Make the mat worth investigating', art: 'mat', labels: ['A clear station', 'Reward curiosity'], instructions: 'Place the mat on a non-slip floor in a quiet room. Let your dog notice it. Mark and reward a look, a step toward it or another small voluntary interaction. Keep the reward close enough to support the next easy attempt.', why: 'Breaking the task into small choices helps the dog discover what works without being pushed or placed on the mat.', practice: 'Reward one small interaction with the mat. Give your dog room to move away between attempts.', fix: 'If your dog avoids it, check the surface, position and material. Start farther away and reward a small glance toward it.', alt: 'Diagram of a dog looking toward a green mat, with a reward marking a first voluntary step in its direction.' },
      { title: 'Build up to four paws on the mat', art: 'approach', labels: ['One paw at a time', 'Four paws earns a reward'], instructions: 'Reward closer approaches, then paws on the mat. As your dog understands the pattern, reward all four paws on it. Toss a reward away from the mat to reset and give them another chance to choose to return.', why: 'The reset makes repeated practice possible without physically moving the dog. It also checks that returning is their own action.', practice: 'Try one or two returns after a reset. Stop while your dog is still interested.', fix: 'If the dog gets stuck, make the next target smaller: a look or a single paw can be the right starting point.', alt: 'Diagram of a dog stepping onto the mat with four paw positions highlighted and a reset reward placed off to one side.' },
      { title: 'Add a cue and a little time', art: 'stay', labels: ['“Mat” before movement', 'Build time gradually'], instructions: 'When your dog regularly moves onto the mat, add a cue just before they do it. Reward on the mat. Gradually wait a little longer between rewards, keeping the delay short enough that your dog can succeed.', why: 'The cue names a familiar action. Duration is a separate skill and should grow in small, comfortable steps.', practice: 'Use your cue once, reward arrival, then reward one brief moment of staying before releasing.', fix: 'If your dog leaves, reduce the duration. Do not restrain them on the mat or expect a long stay immediately.', alt: 'Diagram showing a dog on a mat, a cue bubble saying “mat”, and a short timer representing a brief rewarded pause.' },
      { title: 'Teach a release and add real-life practice', art: 'release', labels: ['Clear release word', 'One small distraction'], instructions: 'Say a consistent release word, then encourage your dog to move off the mat. Practise the arrival, short pause and release together. Later, add a small real-life distraction such as your taking one step away.', why: 'A clear ending helps the dog understand when the task is finished. Easy real-life repetitions help the skill transfer beyond the training session.', practice: 'Try one complete sequence: cue, arrive, reward, short pause, release and break.', fix: 'Busy meal preparation or visitors may be too difficult at first. Practise in easier conditions before using the mat in those situations.', alt: 'Diagram showing a dog leaving its mat after a release cue, with an open path toward a break area.' }
    ]
  },
  care: {
    goal: 'Build a day that balances essentials, rest, movement and meaningful choice.',
    kit: ['Fresh water and a suitable diet', 'A comfortable quiet rest area', 'Safe enrichment choices', 'Your veterinary team’s contact details'],
    note: 'Age, health, weather and individual preferences affect what your dog needs. Ask your veterinary team about diet, preventive care and exercise for your own dog.',
    source: 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs', sourceName: 'RSPCA: caring for dogs',
    steps: [
      { title: 'Start with water, food and comfort', art: 'water', labels: ['Fresh water', 'Individual needs'], instructions: 'Check that fresh water is available and the feeding arrangement suits your dog. Choose an appropriate diet with your veterinary team. Keep eating and drinking areas clean, accessible and calm.', why: 'Basic comfort comes before training. Dogs differ in their diet and health needs, so a universal online schedule is not enough.', practice: 'Check the water bowl and make one small improvement to the feeding or drinking area if needed.', fix: 'A change in appetite, drinking or comfort deserves veterinary advice rather than a training workaround.', alt: 'Diagram of an accessible fresh water bowl and food bowl in a calm area, with the dog able to approach comfortably.' },
      { title: 'Protect quiet, undisturbed rest', art: 'rest', labels: ['Comfortable bed', 'Do not disturb'], instructions: 'Provide a comfortable resting place away from busy routes. Let your dog retreat there without being followed. Help everyone in the household understand that a resting dog should be left in peace.', why: 'Rest is part of a balanced day. A quiet retreat also gives the dog a way to cope when the environment becomes busy.', practice: 'Look at the rest area from the dog’s point of view: noise, draughts, foot traffic and access.', fix: 'If your dog cannot settle or seems uncomfortable, consider the environment and speak with your vet if the change is unusual.', alt: 'Diagram of a dog resting on a bed in a quiet corner, with household activity kept outside a clear rest boundary.' },
      { title: 'Offer movement and enrichment with choice', art: 'sniff', labels: ['Time to sniff', 'Choose an activity'], instructions: 'Offer safe movement appropriate to your dog and the conditions. Include time to sniff and explore. A food puzzle, a scent game or a short reward-based lesson can add variety, but your dog can also choose a break.', why: 'Mental activity and choice complement physical movement. More intensity is not automatically better.', practice: 'Offer one easy enrichment activity and watch whether your dog engages willingly or prefers to stop.', fix: 'If the activity causes frustration or frantic behaviour, simplify it or pause. Supervise toys and remove anything damaged or unsafe.', alt: 'Diagram of a dog following a short sniffing trail, with separate options for a simple puzzle and a quiet break.' },
      { title: 'Notice patterns and plan support', art: 'check', labels: ['Observe changes', 'Ask your vet'], instructions: 'Keep a light-touch record of what helps your dog feel comfortable: rest, meals, walks and activities. Maintain preventive care with your veterinary team and ask about any persistent change in behaviour or health.', why: 'A familiar routine makes changes easier to notice. A record can help you describe the situation clearly when you need professional advice.', practice: 'Note one thing your dog enjoyed today and one thing you would make easier tomorrow.', fix: 'Do not use a checklist to ignore a dog that seems unwell. New or concerning symptoms need appropriate veterinary support.', alt: 'Diagram of a weekly care notebook with rest, food and activity entries, beside a veterinary contact card.' }
    ]
  }
};

